35	/**
36	 * Implementation of RequestRateLimiter specific to query request types. Most of the actual work is
37	 * delegated to the parent class but specific configurations and parsing are handled by this class.
38	 */
39	public class QueryRateLimiter extends RequestRateLimiter {
40	  private static final ObjectMapper mapper = SolrJacksonAnnotationInspector.createObjectMapper();
41	
42	  public QueryRateLimiter(SolrZkClient solrZkClient) {
43	    super(constructQueryRateLimiterConfig(solrZkClient));
44	  }
