96	  private static void constructQueryRateLimiterConfigInternal(
97	      RateLimiterPayload rateLimiterMeta, RateLimiterConfig rateLimiterConfig) {
98	
99	    if (rateLimiterMeta == null) {
100	      // No Rate limiter configuration defined in clusterprops.json
101	      return;
102	    }
103	
104	    if (rateLimiterMeta.allowedRequests != null) {
105	      rateLimiterConfig.allowedRequests = rateLimiterMeta.allowedRequests.intValue();
106	    }
107	
108	    if (rateLimiterMeta.enabled != null) {
109	      rateLimiterConfig.isEnabled = rateLimiterMeta.enabled;
110	    }
111	
112	    if (rateLimiterMeta.guaranteedSlots != null) {
113	      rateLimiterConfig.guaranteedSlotsThreshold = rateLimiterMeta.guaranteedSlots;
114	    }
115	
116	    if (rateLimiterMeta.slotBorrowingEnabled != null) {
117	      rateLimiterConfig.isSlotBorrowingEnabled = rateLimiterMeta.slotBorrowingEnabled;
118	    }
119	
120	    if (rateLimiterMeta.slotAcquisitionTimeoutInMS != null) {
121	      rateLimiterConfig.waitForSlotAcquisition =
122	          rateLimiterMeta.slotAcquisitionTimeoutInMS.longValue();
123	    }
124	  }
